  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']
    # Build edge list with mutual reachability
    edges = []
    for a, b, d in distances:
        mr = max(core[a], core[b], d)
        # canonicalize endpoints: sort lexicographically
        if a < b:
            edges.append((mr, a, b))
        else:
            edges.append((mr, b, a))
    # sort by mr, then first endpoint, then second endpoint
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    # Union-Find
    parent = {}
    rank = {}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    for n in nodes:
        parent[n] = n
        rank[n] = 0
    mst_edges = []
    total_weight = 0.0
    for mr, a, b in edges:
        if len(mst_edges) == len(nodes) - 1:
            break
        if union(a, b):
            mst_edges.append([a, b, mr])
            total_weight += mr
    # assume connected; no need to check
    return {'mst_edges': mst_edges, 'total_weight': total_weight}
